/* Base mobile styles */
.container {
  width: 100%;
  padding: 1rem;
}

.nav-menu {
  display: none;
  flex-direction: column;
  gap: 0.5rem;
}

.hamburger {
  display: block;
  font-size: 1.5rem;
  cursor: pointer;
}

.grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1rem;
}

.card {
  padding: 1rem;
  border: 1px solid #ddd;
  border-radius: 8px;
}

/* Tablet breakpoint */
@media (min-width: 768px) {
  .container {
    max-width: 720px;
    margin: 0 auto;
  }

  .nav-menu {
    display: flex;
    flex-direction: row;
    gap: 1.5rem;
  }

  .hamburger {
    display: none;
  }

  .grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

/* Desktop breakpoint */
@media (min-width: 1024px) {
  .container {
    max-width: 960px;
  }

  .grid {
    grid-template-columns: repeat(3, 1fr);
  }

  .card {
    padding: 1.5rem;
  }
}
